namespace Vialiq.Core.Models;

using System.Collections.Generic;

/// <summary>
/// Change manifest generated by the Migration Diff Engine during protocol upversioning.
/// Pinpoints the exact modified forms, visits, and codelists requiring cache rebuild.
/// </summary>
public sealed record ProtocolAmendmentManifest(
    string AmendmentId,
    string TenantId,
    string StudyId,
    string TargetVersion,
    IReadOnlyList<string> ModifiedFormIds,
    IReadOnlyList<string> ModifiedVisitIds,
    IReadOnlyList<string> ModifiedCodelistIds,
    bool RequiresRetrospectiveRecalculation = false);
